33: MemoryMappedFileReader::MemoryMappedFileReader(const std::string &filePath) {
34: #ifdef _WIN32
35:   HANDLE hFile = CreateFile(filePath.c_str(), GENERIC_READ, 0, NULL,
36:                             OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
37:   if (hFile == INVALID_HANDLE_VALUE) {
38:     throw(std::runtime_error("Error opening file " + filePath + "."));
39:   }
40: 
41:   // Get file size
42:   LARGE_INTEGER fileSize;
43:   if (!GetFileSizeEx(hFile, &fileSize)) {
44:     CloseHandle(hFile);
45:     throw(std::runtime_error("Error reading file " + filePath + "."));
46:   }
47:   d_size = static_cast<size_t>(fileSize.QuadPart);
48: 
49:   // Create a file mapping
50:   HANDLE hMapping = CreateFileMapping(hFile, NULL, PAGE_READONLY, 0, 0, NULL);
51:   if (hMapping == NULL) {
52:     CloseHandle(hFile);
53:     throw(std::runtime_error("Error reading file " + filePath + "."));
54:   }
55: 
56:   // Map the file into memory
57:   d_mappedMemory =
58:       static_cast<char *>(MapViewOfFile(hMapping, FILE_MAP_READ, 0, 0, 0));
59:   if (d_mappedMemory == NULL) {
60:     CloseHandle(hMapping);
61:     CloseHandle(hFile);
62:     throw(std::runtime_error("Error reading file " + filePath + "."));
63:   }
64: 
65:   CloseHandle(hMapping);  // Handle is no longer needed once mapped
66:   CloseHandle(hFile);     // File handle is no longer needed
67: #else
68:   int fd = open(filePath.c_str(), O_RDWR);
69:   if (fd == -1) {
70:     BOOST_LOG(rdErrorLog) << "Error opening file.\n";
71:     throw(std::runtime_error("Error opening file " + filePath + "."));
72:   }
73: 
74:   // Get file size
75:   struct stat fileStat;
76:   if (fstat(fd, &fileStat) == -1) {
77:     close(fd);
78:     throw(std::runtime_error("Error reading file " + filePath + "."));
79:   }
80:   d_size = static_cast<size_t>(fileStat.st_size);
81: 
82:   // Memory map the file
83:   d_mappedMemory =
84:       static_cast<char *>(mmap(NULL, d_size, PROT_READ, MAP_SHARED, fd, 0));
85:   if (d_mappedMemory == MAP_FAILED) {
86:     BOOST_LOG(rdErrorLog) << "Error mapping file.\n";
87:     close(fd);
88:     throw(std::runtime_error("Error reading file " + filePath + "."));
89:   }
90: 
91:   close(fd);  // File descriptor is no longer needed
92: #endif
93: }
