19: //
20: //  Uses the Depict DLL to generate a Mol file (on disk) for a
21: //  SMILES.
22: //
23: //  ARGUMENTS:
24: //    smi:     the SMILES string to be converted
25: //    fName:   the name of the output file
26: //    dllName: (OPTIONAL) the name of the actual DLL to be opened.  The path
27: //             to the DLL is taken from the environment (see below).
28: //
29: //  RETURNS:
30: //   1 on success, 0 otherwise
31: //
32: //  NOTES:
33: //   - To use the DLL, it's essential that the COMBICHEM_ROOT and
34: //   COMBICHEM_RELEASE
35: //     environment variables be set.  If this isn't done, this whole process
36: //     will fail.
37: //   - The Depict DLL is not re-entrant, which means it can't be used from
38: //   multiple
39: //     threads at the same time.  We're going to try and minimize this problem
40: //     by
41: //     leaving it open for as short a period of time as possible.
42: //     Still, opening the DLL may fail, in which case we'll return 0 for
43: //     failure.
44: //     You can always try again.
45: //
46: //*************************************************************************************
47: int SmilesToMolFileDLL(std::string smi, std::string fName,
48:                        std::string dllName) {
49:   // std::string dllName="c:/glandrum/dgen/combi/bin/depict32-0.dll";
50:   const char *root = getenv("COMBICHEM_ROOT");
51:   const char *release = getenv("COMBICHEM_RELEASE");
52:   if (!root || !release) {
53:     BOOST_LOG(rdErrorLog) << "ERROR: COMBICHEM_ROOT and COMBICHEM_RELEASE must "
54:                              "be set to use depictor\n";
55:     return 0;
56:   }
57:   std::string fullName = root;
58:   fullName += std::string("/") + release;
59:   fullName += std::string("/bin/") + dllName;
60: 
61:   Depictor_TwoArgFunc func1;
62:   HINSTANCE hDLL;
63:   hDLL = LoadLibrary(fullName.c_str());
64:   if (!hDLL) {
65:     BOOST_LOG(rdErrorLog) << "ERROR: could not load depict32.dll\n"
66:                           << std::endl;
67:     return 0;
68:   }
69:   func1 = (Depictor_TwoArgFunc)GetProcAddress(hDLL, "SMILESSTRINGTOMOLFILE");
70:   if (!func1) {
71:     FreeLibrary(hDLL);
72:     BOOST_LOG(rdErrorLog)
73:         << "ERROR: could not find SmilesToMolFile function in DLL\n"
74:         << std::endl;
75:     return 0;
76:   }
77:   func1(smi.c_str(), fName.c_str());
78: 
79:   FreeLibrary(hDLL);
80:   return 1;
81: }
