41: bool isAtomCandForChiralH(const RWMol &mol, const Atom *atom) {
42:   // conditions for needing a chiral H:
43:   //   - stereochem specified
44:   //   - in at least two rings
45:   return mol.getRingInfo()->isInitialized() &&
46:          mol.getRingInfo()->numAtomRings(atom->getIdx()) > 1u &&
47:          (atom->getChiralTag() == Atom::CHI_TETRAHEDRAL_CCW ||
48:           atom->getChiralTag() == Atom::CHI_TETRAHEDRAL_CW);
49: }
50: }  // end of anonymous namespace
51: 
52: void prepareMolForDrawing(RWMol &mol, bool kekulize, bool addChiralHs,
53:                           bool wedgeBonds, bool forceCoords, bool wavyBonds) {
54:   if (kekulize) {
55:     RDLog::LogStateSetter blocker;
56:     MolOps::KekulizeIfPossible(
57:         mol, false);  // kekulize, but keep the aromatic flags!
58:   }
59:   if (addChiralHs) {
60:     std::vector<unsigned int> chiralAts;
61:     for (auto atom : mol.atoms()) {
62:       if (isAtomCandForChiralH(mol, atom)) {
63:         chiralAts.push_back(atom->getIdx());
64:       }
65:     }
66:     if (chiralAts.size()) {
67:       bool addCoords = false;
68:       if (!forceCoords && mol.getNumConformers()) {
69:         addCoords = true;
70:       }
71:       MolOps::addHs(mol, false, addCoords, &chiralAts);
72:     }
73:   }
74:   if (forceCoords || !mol.getNumConformers()) {
75:     // compute 2D coordinates in a standard orientation:
76:     const bool canonOrient = true;
77:     RDDepict::compute2DCoords(mol, nullptr, canonOrient);
